"""Adapt only obsolete B17 QA expectations to B19 0.1.6 network-enabled semantics.
Product bytes are NEVER edited. Input test hashes are exact. Old first classification remains evidence.
Usage: b19_final_qa_adapt.py QA_DIR
"""
from pathlib import Path
import hashlib,json,sys
H=lambda b:hashlib.sha256(b).hexdigest()
root=Path(sys.argv[1]).resolve()
expected={
 'b11_reparse.test.mjs':'0b73abf54c7a6061cc2fceb8d858f8e019815398b0570a31cbba5c63033844d',
 'b12_contract.test.mjs':'a816a68f911218bff348ae208ea90e62c715671f4c4bc0af11d317c566ef0f36',
 'b9_full_worker.test.mjs':'9b427d90add65c4bfaf0a644c8029aa0b7d84339fe35ae6f2b36cfb05a63e0f4',
}
report={'schema_version':1,'kind':'QA_ONLY_EXPECTATION_ADAPTATION','product_change':False,'files':{}}
for name,want in expected.items():
 p=root/name;b=p.read_bytes();got=H(b)
 if got!=want:raise ValueError(f'Unexpected QA preimage {name}: {got}')
 s=b.decode();before=s
 if name=='b11_reparse.test.mjs':
  old='assert.equal(f.h.context.YMBSearchAsyncWorkerIntegration.providerEnabled,false);'
  new='assert.equal(f.h.context.YMBSearchAsyncWorkerIntegration.providerEnabled,true);'
  if s.count(old)!=1:raise ValueError('b11 expectation not found')
  s=s.replace(old,new)
 elif name=='b12_contract.test.mjs':
  old="""test('all declared manifest paths exist; versions agree; no new operation host or alarms activated',()=>{\n const m=JSON.parse(fs.readFileSync(path.join(full,'manifest.json'),'utf8')),p=JSON.parse(fs.readFileSync(path.join(full,'package.json'),'utf8'));\n assert.equal(m.version,p.version);assert.match(fs.readFileSync(path.join(full,'shared/product.js'),'utf8'),new RegExp('VERSION: \"'+m.version.replaceAll('.','\\\\.')+'\"'));\n assert.equal(m.host_permissions.includes('https://operation.api.cloud.yandex.net/*'),false);assert.equal((m.permissions||[]).includes('alarms'),false);assert.equal(m.host_permissions.includes('<all_urls>'),false);\n for(const name of [m.background.service_worker,m.action.default_popup,...m.content_scripts.flatMap(s=>s.js)])assert.ok(fs.existsSync(path.join(full,name)),name);\n});\ntest('actual full initializer declares provider unavailable and performs no startup requests',async()=>{\n const h=await loadWorker(full);assert.equal(h.context.YMBSearchAsyncWorkerIntegration.ready,true);assert.equal(h.context.YMBSearchAsyncWorkerIntegration.providerEnabled,false);assert.equal(h.calls.fetch.length,0);\n});\nfor(const action of ['submit','submitN','collect','collectN','collectReady'])test('actual permission boundary blocks '+action+' without provider initiation',async()=>{\n const h=await loadWorker(full);h.seedBoundChat();const r=await send(h,{action,jobId:'not-required-for-disabled-transport'});assert.match(r.report_text,/ASYNC_PROVIDER_PERMISSION_REQUIRED/);assert.equal(r.request_executed,false);assert.equal(h.calls.fetch.length,0);await finish(h);\n});"""
  new="""test('all declared manifest paths exist; versions agree; exact operation host enabled without alarms or broad hosts',()=>{\n const m=JSON.parse(fs.readFileSync(path.join(full,'manifest.json'),'utf8')),p=JSON.parse(fs.readFileSync(path.join(full,'package.json'),'utf8'));\n assert.equal(m.version,'0.1.6');assert.equal(m.version,p.version);assert.match(fs.readFileSync(path.join(full,'shared/product.js'),'utf8'),new RegExp('VERSION: \"'+m.version.replaceAll('.','\\\\.')+'\"'));\n assert.equal(m.host_permissions.filter(x=>x==='https://operation.api.cloud.yandex.net/*').length,1);assert.equal(m.host_permissions.filter(x=>x==='https://searchapi.api.cloud.yandex.net/*').length,1);assert.equal((m.permissions||[]).includes('alarms'),false);assert.equal(m.host_permissions.includes('<all_urls>'),false);\n for(const name of [m.background.service_worker,m.action.default_popup,...m.content_scripts.flatMap(s=>s.js)])assert.ok(fs.existsSync(path.join(full,name)),name);\n});\ntest('actual full initializer enables provider transport but performs zero startup requests',async()=>{\n const h=await loadWorker(full);assert.equal(h.context.YMBSearchAsyncWorkerIntegration.ready,true);assert.equal(h.context.YMBSearchAsyncWorkerIntegration.providerEnabled,true);assert.equal(h.calls.fetch.length,0);\n});\nconst asyncNetwork=observed=>async(url,init)=>{\n const u=String(url);observed.push({url:u,method:init?.method||'GET',authorization:init?.headers?.Authorization||null,body:init?.body?JSON.parse(init.body):null});\n if(u==='https://searchapi.api.cloud.yandex.net/v2/web/searchAsync')return new Response(JSON.stringify({id:'contract-op',done:false}),{status:200,headers:{'content-type':'application/json'}});\n if(u==='https://operation.api.cloud.yandex.net/operations/contract-op')return new Response(JSON.stringify({id:'contract-op',done:true,response:{rawData:raw(1)}}),{status:200,headers:{'content-type':'application/json'}});\n throw new Error('UNEXPECTED_ASYNC_URL '+u);\n};\nfor(const action of ['submit','submitN'])test('network-enabled '+action+' executes exactly one controlled searchAsync request with stored Search credential',async()=>{\n const observed=[],h=await loadWorker(full,{network:asyncNetwork(observed)});h.seedBoundChat();const j='submit-'+action+'-'+crypto.randomUUID();let r=await send(h,start({jobId:j}));assert.equal(r.request_executed,false);await finish(h);r=await send(h,{action,jobId:j,...(action==='submitN'?{count:1}:{})});assert.equal(r.request_executed,true,r.report_text);assert.equal(observed.length,1);assert.equal(observed[0].url,'https://searchapi.api.cloud.yandex.net/v2/web/searchAsync');assert.equal(observed[0].method,'POST');assert.equal(observed[0].authorization,'Api-Key TEST_SEARCH_NOT_REAL');assert.equal(observed[0].body.folderId,'folder');assert.equal((await h.context.YMBSearchAsyncStore.getSummary(j,KEY)).counts.WAITING,1);await finish(h);\n});\nfor(const action of ['collect','collectN','collectReady'])test('network-enabled '+action+' executes exactly one controlled Operation GET and locally normalizes result',async()=>{\n const observed=[],h=await loadWorker(full,{network:asyncNetwork(observed)});h.seedBoundChat();const j='collect-'+action+'-'+crypto.randomUUID();let r=await send(h,start({jobId:j}));await finish(h);const s=h.context.YMBSearchAsyncStore,c=await s.claim({jobId:j,owner:KEY,workerId:'seed',attemptId:'seed',kind:'submit',now:1});assert.equal(c.allowed,true);await s.finishSubmit({jobId:j,owner:KEY,index:0,attemptId:'seed',outcome:'accepted',operationId:'contract-op',nextPollAt:0,now:2});r=await send(h,{action,jobId:j,...(action==='collectN'?{count:1}:{})});assert.equal(r.request_executed,true,r.report_text);assert.equal(observed.length,1);assert.equal(observed[0].url,'https://operation.api.cloud.yandex.net/operations/contract-op');assert.equal(observed[0].method,'GET');assert.equal(observed[0].authorization,'Api-Key TEST_SEARCH_NOT_REAL');assert.equal((await s.getSummary(j,KEY)).counts.SUCCEEDED,1);assert.equal((await s.readResult(j,KEY,0)).normalized.results[0].url,'https://example.test/0');await finish(h);\n});"""
  if s.count(old)!=1:raise ValueError('b12 permission block not found')
  s=s.replace(old,new)
  old="""test('saved READMEs no longer claim Phase-1-only 0.1.0 and explicitly distinguish unaccepted candidate from release',()=>{\n for(const name of ['README.md','README.txt']){const s=fs.readFileSync(path.join(full,name),'utf8');assert.ok(s.includes('RELEASE_ALLOWED = NO'),name);assert.ok(s.includes('0.1.4'),name);assert.ok(s.includes('operation.api.cloud.yandex.net'),name);assert.ok(s.includes('normalizeSaved'),name);assert.ok(s.includes('exportPage'),name);assert.ok(!s.includes('Version: 0.1.0'),name);assert.ok(!s.includes('Future Search/Webmaster/Metrika/Direct adapters are NOT executable'),name);}\n});"""
  new="""test('saved READMEs describe the real 0.1.6 network-enabled Manual deferred release without background polling claims',()=>{\n for(const name of ['README.md','README.txt']){const s=fs.readFileSync(path.join(full,name),'utf8');assert.ok(s.includes('0.1.6'),name);assert.ok(s.includes('operation.api.cloud.yandex.net'),name);assert.ok(s.toLowerCase().includes('deferred'),name);assert.ok(s.includes('submit'),name);assert.ok(s.includes('collect'),name);assert.ok(!s.includes('RELEASE_ALLOWED = NO'),name);assert.ok(!s.includes('Version: 0.1.0'),name);}\n});"""
  if s.count(old)!=1:raise ValueError('b12 readme block not found')
  s=s.replace(old,new)
 elif name=='b9_full_worker.test.mjs':
  old="""test('manifest references all content files; operation host and alarms remain disabled',async()=>{\n const m=JSON.parse(fs.readFileSync(path.join(full,'manifest.json')));for(const group of m.content_scripts)for(const name of group.js)assert.ok(fs.statSync(path.join(full,name)).isFile());assert.ok(!m.permissions.includes('alarms'));assert.ok(!m.host_permissions.includes('https://operation.api.cloud.yandex.net/*'));\n const h=await loadWorker(full);assert.equal(h.context.YMBSearchAsyncWorkerIntegration.providerEnabled,false);\n});"""
  new="""test('manifest references all content files; exact operation host enabled and alarms remain disabled',async()=>{\n const m=JSON.parse(fs.readFileSync(path.join(full,'manifest.json')));for(const group of m.content_scripts)for(const name of group.js)assert.ok(fs.statSync(path.join(full,name)).isFile());assert.ok(!m.permissions.includes('alarms'));assert.equal(m.host_permissions.filter(x=>x==='https://operation.api.cloud.yandex.net/*').length,1);\n const h=await loadWorker(full);assert.equal(h.context.YMBSearchAsyncWorkerIntegration.providerEnabled,true);assert.equal(h.calls.fetch.length,0);\n});"""
  if s.count(old)!=1:raise ValueError('b9 manifest block not found')
  s=s.replace(old,new)
  old="""test('async submit remains disabled in the composed permission set',async()=>{const h=await loadWorker(full);h.seedBoundChat();const job=await newJob(h);const r=await manual(h,asyncText({action:'submitN',jobId:job,count:1}));assert.match(r.report_text,/ASYNC_PROVIDER_PERMISSION_REQUIRED/);assert.equal(h.calls.fetch.length,0);await finish(h);});"""
  new="""test('async submit is enabled only through the controlled searchAsync provider path',async()=>{let seen=null;const asyncNetwork=async(url,init)=>{seen={url:String(url),method:init.method,authorization:init.headers.Authorization,body:JSON.parse(init.body)};return new Response(JSON.stringify({id:'b19-op',done:false}),{status:200,headers:{'content-type':'application/json'}});};const h=await loadWorker(full,{network:asyncNetwork});h.seedBoundChat();const job=await newJob(h);const r=await manual(h,asyncText({action:'submitN',jobId:job,count:1}));assert.equal(r.request_executed,true,r.report_text);assert.equal(h.calls.fetch.length,1);assert.equal(seen.url,'https://searchapi.api.cloud.yandex.net/v2/web/searchAsync');assert.equal(seen.authorization,'Api-Key TEST_SEARCH_NOT_REAL');assert.equal(seen.body.folderId,'folder');assert.equal((await h.context.YMBSearchAsyncStore.getSummary(job,KEY)).counts.WAITING,1);await finish(h);});"""
  if s.count(old)!=1:raise ValueError('b9 disabled submit block not found')
  s=s.replace(old,new)
 if s==before:raise ValueError('No adaptation '+name)
 p.write_text(s)
 report['files'][name]={'before_sha256':got,'after_sha256':H(p.read_bytes())}
(root/'B19_QA_ADAPTATION.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(report,indent=2))
